<?php $cliente = $cuenta['cliente']; $mensaje = $_SESSION['mensaje_clientes'] ?? null; unset($_SESSION['mensaje_clientes']); $tituloPagina = 'Estado de cuenta'; require APP_PATH . 'Views/layouts/pos_header.php'; ?>
<section class="catalogo-encabezado"><div><span class="eyebrow">Cuenta corriente</span><h1><?php echo htmlspecialchars($cliente['nombre']); ?></h1><p><?php echo htmlspecialchars($cliente['rtn_identidad'] ?? ''); ?> | <?php echo htmlspecialchars($cliente['telefono'] ?? ''); ?></p></div><button class="btn-pos btn-success" type="button" onclick="document.getElementById('modal-abono').hidden=false">Registrar Nuevo Abono</button></section>
<?php if ($mensaje): ?><div class="alerta alerta-exito"><?php echo htmlspecialchars($mensaje); ?><?php if (!empty($_SESSION['ultimo_abono_id'])): ?> <a href="<?php echo URL_BASE; ?>clientes/abono/ticket/<?php echo (int)$_SESSION['ultimo_abono_id']; ?>">Imprimir comprobante</a><?php unset($_SESSION['ultimo_abono_id']); endif; ?></div><?php endif; ?>
<section class="resumen-caja"><div><span>Límite de crédito</span><strong><?php echo formatearMoneda($cliente['limite_credito']); ?></strong></div><div class="esperado"><span>Saldo pendiente</span><strong><?php echo formatearMoneda($cliente['saldo_pendiente']); ?></strong></div><div><span>Crédito disponible</span><strong><?php echo formatearMoneda(max(0,(float)$cliente['limite_credito']-(float)$cliente['saldo_pendiente'])); ?></strong></div></section>
<section class="tarjeta"><h2 class="tarjeta-titulo">Historial de compras a crédito</h2><div class="tabla-responsive"><table class="tabla-catalogo"><thead><tr><th>Fecha</th><th>Folio</th><th>Cargo</th></tr></thead><tbody><?php if (!$cuenta['compras']): ?><tr><td colspan="3" class="tabla-vacia">No hay compras a crédito.</td></tr><?php endif; ?><?php foreach ($cuenta['compras'] as $compra): ?><tr><td><?php echo date('d/m/Y H:i',strtotime($compra['fecha'])); ?></td><td><?php echo htmlspecialchars($compra['folio']); ?></td><td><?php echo formatearMoneda($compra['cargo']); ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="tarjeta"><h2 class="tarjeta-titulo">Historial de abonos</h2><div class="tabla-responsive"><table class="tabla-catalogo"><thead><tr><th>Fecha</th><th>Forma de pago</th><th>Observación</th><th>Abono</th></tr></thead><tbody><?php if (!$cuenta['abonos']): ?><tr><td colspan="4" class="tabla-vacia">No hay abonos registrados.</td></tr></tr><?php endif; ?><?php foreach ($cuenta['abonos'] as $abono): ?><tr><td><?php echo date('d/m/Y H:i',strtotime($abono['fecha'])); ?></td><td><?php echo htmlspecialchars($abono['forma_pago']); ?></td><td><?php echo htmlspecialchars($abono['observacion'] ?? ''); ?></td><td><?php echo formatearMoneda($abono['abono']); ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="modal-simple" id="modal-abono" hidden><div class="tarjeta"><h2 class="tarjeta-titulo">Registrar abono</h2><form method="POST" action="<?php echo URL_BASE; ?>clientes/abonar" class="form-grid"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars(csrf_token()); ?>"><input type="hidden" name="cliente_id" value="<?php echo (int)$cliente['id']; ?>"><div class="campo"><label>Monto (L)</label><input name="monto" type="number" min="0.01" max="<?php echo htmlspecialchars($cliente['saldo_pendiente']); ?>" step="0.01" required></div><div class="campo"><label>Forma de pago</label><select name="forma_pago"><option value="efectivo">Efectivo</option><option value="tarjeta">Tarjeta</option><option value="transferencia">Transferencia</option></select></div><div class="campo campo-ancho"><label>Observación</label><input name="observacion" maxlength="255"></div><div class="form-acciones"><button type="button" class="btn btn-ligero" onclick="document.getElementById('modal-abono').hidden=true">Cancelar</button><button class="btn btn-exito">Guardar abono</button></div></form></div></div>
